def features(q):
    import itertools as it
    fs = []
    names = []

    def add(name, a):
        names.append(name)
        fs.append(a)
    for k in range(1, 5):
        for ii in it.combinations_with_replacement(range(4), k):
            add(''.join(map(str, ii)), np.prod(q[:, ii], axis=1))
    for i in range(4):
        for j in range(i + 1, 4):
            for k in [-1, 1]:
                add(f'ratio{i}{j}{k}', q[:, i] / (1 + (q[:, i] + k * q[:, j]) ** 2))
    for i in range(4):
        for w in [0.5, 1, 1.5, 2, 2.5, 3]:
            for (name, fn) in [('sin', np.sin), ('cos', np.cos), ('tanh', np.tanh), ('rational', lambda p: p / (1 + p * p))]:
                add(f'{name}({w}*{i})', fn(w * q[:, i]))
    for (i, j) in it.combinations(range(4), 2):
        for sign in [-1, 1]:
            for w in [1, 2]:
                for (name, fn) in [('sin', np.sin), ('cos', np.cos), ('tanh', np.tanh)]:
                    add(f'{name}({w}*({i}+{sign}*{j}))', fn(w * (q[:, i] + sign * q[:, j])))
    return (np.column_stack(fs), np.array(names))
